begin;
do $curate$ declare r jsonb; bid uuid; applied jsonb; begin
for r in select value from jsonb_array_elements('[{"name": "Art Pet Mobile Grooming", "category": "Pet Services", "city": "Service area only", "address": null, "phone": "(209) 554-6445", "website": "https://www.artpetgrooming.com/", "source_url": "https://www.artpetgrooming.com/locations/lathrop/", "duplicate_key": "artpetgrooming.com", "areas": ["Lathrop", "Manteca"], "tags": ["mobile dog grooming", "dog grooming"], "description": "Official Lathrop and Manteca pages advertise mobile dog bathing, haircuts and nail care at the customer\u2019s home. The published San Joaquin contact is used here. Confirm your address, dog eligibility, mobile setup, full quote and appointment dates directly. No public visitor office or holiday availability established.", "note": "Official homepage, Lathrop and Manteca location pages read in the normal browser November14,2026 after the web fetch returned access denied. Checked identity, explicit mobile dog-grooming coverage in Lathrop/Manteca, advertised baths/haircuts/nail care and phone2095546445 specifically labeled San Joaquin. Central8666232993 booking line also shown; regional number selected deliberately. No cat-care/dog-walking tag inferred from unrelated homepage tabs; no extra cities, address from secondary directories, prices, rankings/review counts, credentials, methods/safety or availability adopted. No images/testimonials reused; no booking/contact submitted. Sources: https://www.artpetgrooming.com/ https://www.artpetgrooming.com/locations/lathrop/ https://www.artpetgrooming.com/locations/manteca/"}, {"name": "Bone-a-Fide Dog Training", "category": "Pet Services", "city": "Manteca", "address": null, "phone": "(209) 740-7420", "website": "https://bfdogtraining.com/", "source_url": "https://bfdogtraining.com/in-home-lessons", "duplicate_key": "bfdogtraining.com", "areas": ["Manteca"], "tags": ["dog training", "puppy training"], "description": "Manteca-based provider advertising puppy and obedience training through group classes and private lessons, including in-home, park and dog-park sessions. Use the published Manteca contact to confirm location, eligibility, current class or lesson dates, travel fees and total quote. No visitor street office, Lathrop coverage or ordinary boarding established by this check.", "note": "Fresh HTTP200 homepage, contact and in-home lesson pages checked November14,2026. Identity, Manteca office locality, Manteca-specific2097407420 phone (not the separate Iowa number), advertised puppy/obedience group/private training and Manteca home/park lesson context checked. Travel-fee wording outside Manteca is not adopted as coverage for other named cities. Old2019Lathrop reference and September2026class starts not treated as current Lathrop coverage or upcoming available events. No credentials/awards, training results, methods/safety, medical capability, fixed price, class availability or holiday hours independently verified. No images/reviews copied; no form submitted. Sources: https://bfdogtraining.com/ https://bfdogtraining.com/contact-us https://bfdogtraining.com/in-home-lessons"}]'::jsonb) loop
 if exists(select 1 from public.businesses where lower(name)=lower(r->>'name') or website ilike '%'||(r->>'duplicate_key')||'%' or (r->>'phone' is not null and right(regexp_replace(coalesce(phone,''),'[^0-9]','','g'),10)=right(regexp_replace(r->>'phone','[^0-9]','','g'),10))) then raise exception 'Duplicate requires individual review: %',r->>'name'; end if;
 insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values(r->>'name',r->>'category',r->>'city',r->>'address',r->>'phone',r->>'website',r->>'description','approved',true,false,null,0,'editorial_first_party',r->>'source_url','first_party_website_desk_check',now()) returning id into bid;
 insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,r->>'source_url',array['identity','public contact route','website','advertised services','explicit service cities','service limits'],array(select jsonb_array_elements_text(r->'areas')),array(select jsonb_array_elements_text(r->'tags')),r->>'note');
 select to_jsonb(b) into applied from public.businesses b where id=bid;
 insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,applied||jsonb_build_object('service_areas',r->'areas','service_tags',r->'tags','scope_note',r->>'note'),'Individually source-checked directory expansion; no seed publication',r->>'source_url');
end loop;end $curate$;
do $coverage$ declare before_b jsonb; before_c jsonb; after_b jsonb; after_c jsonb; bid uuid:='480a1ad1-747c-4b79-b4c6-1088bbf96e19'; begin
 select to_jsonb(b) into before_b from public.businesses b where id=bid and name='Fresh Pup Pet Grooming' and status='approved' and verified=true for update;
 select to_jsonb(c) into before_c from public.listing_checks c where business_id=bid and service_areas=array['Manteca'];
 if before_b is null or before_c is null then raise exception 'Fresh Pup precondition changed'; end if;
 update public.businesses set description='Website advertises mobile dog grooming for Manteca and Lathrop through dedicated city pages, including baths, haircuts and nail care. Call to confirm the mobile arrangement, your address, dog eligibility, quote and available dates. Other surrounding cities are not established; no visitor office or holiday availability confirmed.' where id=bid;
 update public.listing_checks set service_areas=array['Manteca','Lathrop'],checked_at=now(),source_url='https://freshpuppetgrooming.com/lathrop',scope_note='Coverage expanded November14,2026 after fresh HTTP200 dedicated Lathrop page explicitly named Lathrop and repeated4157703935. Existing same-day Manteca homepage evidence retained. Identity, advertised mobile dog grooming/baths/haircuts/nail care and exact two cities checked; generic surrounding-area wording does not establish Tracy/Mountain House. No prices/promotions, credentials, methods/safety, medical/dental capability, quality or availability independently verified. No photos/testimonials reused and no booking submitted. Sources: https://freshpuppetgrooming.com/ https://freshpuppetgrooming.com/lathrop' where business_id=bid;
 select to_jsonb(b) into after_b from public.businesses b where id=bid;
 select to_jsonb(c) into after_c from public.listing_checks c where business_id=bid;
 insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,before_b||jsonb_build_object('listing_check',before_c),after_b||jsonb_build_object('listing_check',after_c),'Dedicated primary city page establishes additional Lathrop coverage; approval timestamp preserved','https://freshpuppetgrooming.com/lathrop');
end $coverage$;
commit;
select b.id,b.name,b.city,b.verified_at,c.service_areas,c.service_tags,c.checked_at from public.businesses b join public.listing_checks c on c.business_id=b.id where b.website in ('https://www.artpetgrooming.com/','https://bfdogtraining.com/','https://freshpuppetgrooming.com/');
